>> +next:
>> +	spin_lock_irqsave(&cache->tree_lock, flags);
>> +	nr = radix_tree_gang_lookup(&cache->root, (void **)entries, index,
>> +		min((unsigned long)F2FS_ONSTACK_CACHES, end - index));
>> +	if (!nr)
>> +		goto out_unlock;
